// Chat with model gpt-4o-mini through the OpenAI-compatible endpoint
// Node 18+ (global fetch). Run with: npx tsx swfte-call.ts  (export SWFTE_API_KEY first)
const BASE_URL = "https://api.example.test/agents";
const headers: Record<string, string> = {
  Authorization: `Bearer ${process.env.SWFTE_API_KEY}`,
  "Content-Type": "application/json",
};

async function main() {
  const res = await fetch(`${BASE_URL}/v1/chat/completions`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      "model": "gpt-4o-mini",
      "messages": [
        {
          "role": "user",
          "content": "Hello"
        }
      ]
    }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  console.log(data["choices"]?.[0]?.["message"]?.["content"]);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
